WITH houses_by_date AS (SELECT id_owner, FIRST_VALUE(houses) OVER (PARTITION BY dd.date, id_owner ORDER BY ts_house_number_started DESC) AS houses, dd.date AS dt, dd.week_end AS dt_week_end, ts_house_number_started, MAX(ts_house_number_started) OVER (PARTITION BY dd.date, id_owner) AS ts_last_started FROM datalake_pro_owners.owner_houses_quantity_history AS ohqh JOIN dw_public.dim_date AS dd ON dd.date BETWEEN CAST(ohqh.ts_house_number_started AS DATE) AND COALESCE(CAST(ohqh.ts_house_number_ended AS DATE), CURRENT_DATE) WHERE houses >= 5) SELECT id_owner, houses, dt_week_end, STRUCT(year AS year) AS year, STRUCT(month AS month) AS month, STRUCT(day AS day) AS day FROM houses_by_date WHERE ts_house_number_started = ts_last_started AND dt = dt_week_end